using Boll.Core.Content;

namespace Boll.App
{
    /// <summary>Правила видов для экрана «Правила» (утверждает заказчик, CONCEPT §3).</summary>
    public static class RulesText
    {
        const string Common =
            "\n\nОбщее. Касание битком стенки, бампера или движущегося объекта до прицельного шара — не фол. Если нужно касание борта, стенка, бампер или движущийся объект его заменяют. Шар забит, когда его центр упал в лузу. Право разбоя — по жребию. Ничьих нет.";

        const string Controls =
            "\n\nУправление. Ведите палец вокруг битка — кий повернётся (чем дальше от битка, тем точнее). Оттяните палец от битка вдоль кия — это сила (полная на расстоянии 150 dp); отпустили палец — удар. Вернули палец ближе 48 dp к битку и отпустили — удар отменён. Другой способ: задайте силу ползунком справа и нажмите «Удар». Точка удара (накат, оттяжка, боковой винт) — в окне справа внизу.";

        public static string For(GameKind k)
        {
            switch (k)
            {
                case GameKind.Eight:
                    return "«Восьмёрка» (правила WPA)\n\n15 шаров и биток. «8» — в центре третьего ряда треугольника. Разбой с руки из дома. Разбой законный, если забит шар или не меньше 4 шаров с номерами коснулись борта; иначе перерасстановка, разбивает соперник. «8» на разбое без фола — перерасстановка, разбивает тот же игрок.\n\nСтол открыт до первого законно забитого шара; за игроком закрепляется группа этого шара (сплошные 1–7 или полосатые 9–15), за соперником — другая.\n\nФолы: биток никого не коснулся; первым задет не прицельный шар; после касания ничего не забито и никто не дошёл до борта; биток забит. После фола соперник ставит биток с руки.\n\nПеред ударом по «8» касанием выберите лузу. Победа: «8» в выбранную лузу после очистки своей группы без фола. Поражение: «8» раньше времени, не в ту лузу или с фолом.\n\nСчёт — число забитых шаров своей группы." + Common + Controls;
                case GameKind.Nine:
                    return "«Девятка» (правила WPA)\n\nШары 1–9 ромбом: «1» в вершине, «9» в центре. Разбой с руки из дома: первым нужно тронуть «1» и забить шар или довести 4 шара до борта, иначе фол.\n\nПрицельный шар — с наименьшим номером. Фолы — как в «восьмёрке», после фола соперник ставит биток с руки. Забили без фола — бьёте дальше. «9», забитая без фола (в том числе на разбое), — победа. «9», забитая с фолом, возвращается на вершину.\n\nТри фола подряд — поражение, после второго будет предупреждение. Счёт — число шаров, забитых своими ударами." + Common + Controls;
                case GameKind.American:
                    return "«Американка» (русская пирамида)\n\n15 белых шаров и один цветной. Разбой цветным шаром из дома. Перед каждым ударом коснитесь шара, которым будете бить (любой шар стола).\n\nОчко — за каждый шар, забитый после контакта, и за биток, упавший после контакта. Если ничего не забито, хотя бы один шар после контакта должен коснуться двух разных бортов или пересечь центральную линию и коснуться борта, иначе фол. Фол также: биток никого не коснулся; биток забит без контакта.\n\nФол: шары удара возвращаются на заднюю отметку без очков, нарушитель возвращает один свой шар и теряет очко. Ход переходит к сопернику с текущей позиции. Шар, упавший до касания битка (столкнул движущийся объект), очков не даёт и возвращается.\n\nПобеда — 8 очков." + Common + Controls;
                case GameKind.Siberian:
                    return "«Сибирка» (московская пирамида)\n\nКак «Американка», но бьют только цветным битком, прицельные шары — белые.\n\nБиток, упавший после контакта, приносит очко, и следующий удар тот же игрок делает с руки из дома — по шару за линией дома. Удар из дома, где биток первым коснулся шара в доме, — фол. Если за линией дома нет белых шаров, ближайший к линии белый шар ставится на заднюю отметку.\n\nФол: белые шары удара возвращаются, нарушитель отдаёт белый шар с наименьшим номером и теряет очко. Ход сопернику: с руки из дома, если биток забит, иначе с места остановки битка.\n\nПобеда — 8 очков." + Common + Controls;
                default:
                    return "Снукер (правила WPBSA)\n\nОдин фрейм; при равенстве после последнего шара переигрывается чёрный. Очередь: красный, затем цветной (его нужно выбрать кнопкой перед ударом), потом снова красный. Когда красные кончились — цветные по возрастанию: жёлтый 2, зелёный 3, коричневый 4, синий 5, розовый 6, чёрный 7.\n\nПромах — не фол. Биток никого не коснулся — не фол, ход соперника без штрафа (если биток в лузе — с руки в зоне D). Первым тронут неразрешённый шар — фол по WPBSA. Свободный шар и возврат цветных на отметки — по WPBSA; кнопка «Свободный шар» появляется после фола, если биток в снукере.\n\nПобеждает набравший больше очков." + Common + Controls;
            }
        }
    }
}
